#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b;}#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1const int N = 4e5 + 10,inf = 0x3f3f3f3f3f3f3f3f;int T,n,k,ans;vector<int> G[N],deg,t;// 记录每个点邻居为1时的时间 void O_o(){	ans = 0;	cin >> n >> k;	for(int i=1;i<=n;i++){		G[i].clear();	}	deg.assign(n + 1, 0);	t.assign(n + 1,inf);	for(int i=1;i<=n-1;i++){		int u,v;cin >> u >> v;		G[u].push_back(v);		G[v].push_back(u);		deg[u]++;		deg[v]++;	}	queue<int> q;	for(int i=1;i<=n;i++){		if(deg[i] <= 1){			q.push(i);			t[i] = 1;		}	}	while(!q.empty()){		int u = q.front();		q.pop();		for(auto &v : G[u]){			if(t[v] != inf)continue;			deg[v]--;			if(deg[v] <= 1){				t[v] = t[u] + 1;				q.push(v);			}		}	}	for(int i=1;i<=n;i++){		if(t[i] > k){			ans++;		}	}	cout << ans << '\n';} signed main(){	ios::sync_with_stdio(false);	cin.tie(nullptr);cout.tie(nullptr);	cin >> T;	while(T--){		O_o();	}}